export type Mood = "smile" | "wink" | "wave" | "confused";

/** Dannybouy, the hand-drawn mascot. SVGs are generated by scripts/make-mascot.py. Decorative unless `alt` is given. */
export function Mascot({ mood = "smile", className = "", alt = "" }: { mood?: Mood; className?: string; alt?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={`/mascot/dannybouy-${mood}.svg`} alt={alt} width={328} height={312} className={className} />
  );
}
